const boundaryCatalog=window.XP_STATES;
let scenario=boundaryCatalog[params.get('state')]?params.get('state'):'normal';
let recoveryTimer=null;let savedScenarioFavorites=null,savedScenarioSources=null;const originalPersist=persist;persist=function(k,v){if((k==='xp-design-favorites'&&savedScenarioFavorites)||(k==='xp-design-sources'&&savedScenarioSources))return;originalPersist(k,v)};
const originalChannels=channelData.map(c=>({...c}));
const originalBody=body,originalGuide=guide,originalPlayerView=playerView,originalModalView=modalView,originalCard=card;
const unprovidedEpg=new Set(['epg-loading','epg-unconfigured','epg-none','epg-error']);
function scenarioInfo(){return boundaryCatalog[scenario]||boundaryCatalog.normal}
function boundaryAction(label,action,primary=false){return `<button class="${primary?'primary-button':'secondary-button'}" data-boundary-action="${action}">${label}</button>`}
function boundaryPanel(s,inline=false){const audio=scenario==='player-audio-only';const title=audio&&paused?'音频已暂停':s.title;const description=audio&&paused?'频道已暂停。准备好后，可以继续收听。':s.body;const label=audio&&paused?'继续音频':s.action;return `<section class="${inline?'boundary-banner':'boundary-panel'}" data-tone="${s.tone}" aria-label="${s.title}"><span class="boundary-icon">${icon(s.icon)}</span><div><h2>${title}</h2><p>${description}</p>${s.detail?`<div class="boundary-detail">${s.detail}</div>`:''}</div>${inline?boundaryAction(label,s.actionType):`<div class="boundary-actions">${boundaryAction(label,s.actionType,true)}${s.secondary?boundaryAction(s.secondary,s.secondaryType):''}</div>`}</section>`}
function boundaryChannels(){return `<h2 class="boundary-channel-heading">节目单未就绪，也可以直接看频道</h2><div class="boundary-channel-list">${channelData.slice(0,4).map(c=>`<button data-play="${c.id}">${badge(c)}<span><b>${c.name}</b><small>节目信息暂不可用 · 频道可播放</small></span>${icon('play')}</button>`).join('')}</div>`}
function notifyBoundary(){parent.postMessage({type:'xplayer-state',state:scenario,page:player?'player':page},location.origin==='null'?'*':location.origin);const u=new URL(location);u.searchParams.set('state',scenario);history.replaceState(null,'',u)}
function applyScenario(name,{navigateTo=true,notify=true}={}){clearTimeout(recoveryTimer);if(savedScenarioFavorites&&name!=='favorites-empty'&&name!=='list-empty'){favorites=savedScenarioFavorites;savedScenarioFavorites=null}if(savedScenarioSources&&name!=='list-empty'){sources=savedScenarioSources;savedScenarioSources=null}scenario=boundaryCatalog[name]?name:'normal';const s=scenarioInfo();if(['favorites-empty','list-empty'].includes(scenario)){if(!savedScenarioFavorites)savedScenarioFavorites=[...favorites];favorites=[]}if(scenario==='list-empty'){if(!savedScenarioSources)savedScenarioSources=[...sources];sources=[]}document.documentElement.dataset.state=scenario;document.documentElement.dataset.epgUnavailable=String(unprovidedEpg.has(scenario));for(let i=0;i<channelData.length;i++){Object.assign(channelData[i],originalChannels[i]);delete channelData[i].epgMissing;if(unprovidedEpg.has(scenario))Object.assign(channelData[i],{title:'暂无节目单',sub:'频道直播不受影响',next:'暂无节目单',start:'',end:'',progress:0});if(scenario==='epg-partial'&&[2,5,7].includes(channelData[i].id))Object.assign(channelData[i],{epgMissing:true,title:'暂无节目信息',sub:'频道可正常播放',start:'',end:'',next:'',progress:0})}if(navigateTo){if(s.page==='player'){page='home';player=1;showLibrary=false}else{page=s.page;player=null}}if(scenario==='search-empty')query='不存在的频道';else if(s.scope!=='search')query='';render();if(notify)notifyBoundary()}
card=function(c){let h=originalCard(c);if(c.epgMissing)h=h.replace('class="channel-card"','class="channel-card epg-missing"');return h};
guide=function(){const s=scenarioInfo();if(s.scope!=='epg')return originalGuide();if(!s.inline)return intro('节目单','先选好频道，节目安排可以稍后再看。')+boundaryPanel(s)+boundaryChannels()+`<p class="page-footnote">节目单的可用性与直播播放独立。不会因节目单失败阻止选台。</p>`;let html=originalGuide();if(scenario==='epg-stale')html=html.replace('10 月 25 日 · 今天','10 月 24 日 · 缓存').replace('20:42 正在直播','显示昨日缓存').replace('回到现在','刷新节目单').replace('data-action="now"','data-boundary-action="retry-epg"').replaceAll('正在播出','缓存节目').replaceAll('即将播出','缓存节目');return boundaryPanel(s,true)+html};
const originalGuideBlocks=guideBlocks;
guideBlocks=function(c,i){if(!c.epgMissing)return originalGuideBlocks(c,i);return `<div class="epg-missing-block"><div><b>暂无节目信息</b><small>频道可播放，节目单尚未匹配</small></div><button data-play="${c.id}">观看频道 ${icon('arrow')}</button></div>`};
body=function(){const s=scenarioInfo();if(s.scope==='epg'){if(page==='guide')return guide();return boundaryPanel(s,true)+originalBody()}if(s.scope==='network')return boundaryPanel(s,true)+originalBody();if(scenario==='list-empty'&&!['settings','remote'].includes(page))return intro(labels[page]||'播放列表','从第一个播放列表开始。')+boundaryPanel(s);if(s.scope==='channels-empty'&&page==='channels')return intro('全部频道','当前列表 · 0 个有效频道')+boundaryPanel(s);if(s.scope==='sources'&&page==='sources'){if(scenario==='import-error')return boundaryPanel(s,true)+sourcePage();return intro('播放列表','将常看的频道放进自己的空间。')+boundaryPanel(s)}if(s.scope==='search'&&page==='channels')return intro('全部频道','搜索范围：我的电视 · 全部分组')+boundaryPanel(s);if(s.scope==='favorites'&&page==='favorites')return intro('我的收藏','你的专属频道清单，从喜欢开始。')+boundaryPanel(s);if(s.scope==='remote'&&page==='remote')return intro('手机遥控','同一个 Wi-Fi，连接你身边的大屏。')+boundaryPanel(s)+`<div class="boundary-remote-placeholder">${icon('remote')}连接成功后，这里才会显示方向键和文字输入。</div>`;if(s.scope==='sync'&&page==='settings')return boundaryPanel(s)+settingsPage();return originalBody()};
playerView=function(){let html=originalPlayerView();const current=channelData.find(c=>c.id===player);if(current?.epgMissing)html=html.replace('class="player-overlay ', 'class="player-overlay epg-missing ');const s=scenarioInfo();if(s.scope!=='player'&&scenario!=='network-offline')return html;if(scenario==='network-offline')return html.replace('class="player-overlay ', 'class="player-overlay has-boundary ').replace('<div class="player-center">',`<div class="state-player">${boundaryPanel({...boundaryCatalog['player-error'],title:'网络尚未连接',body:'网络恢复后可以重新连接当前频道。',action:'检查并重试',actionType:'retry-network',secondary:'返回频道',secondaryType:'close-player'})}</div><div class="player-center">`);html=html.replace('class="player-overlay ',`class="player-overlay has-boundary ${scenario==='player-audio-only'?'audio-only ':''}${scenario==='player-buffering'?'buffering ':''}`);return html.replace('<div class="player-center">',`<div class="state-player">${boundaryPanel(s)}</div><div class="player-center">`)};
modalView=function(){if(modal?.kind==='epg-config')return `<div class="modal-backdrop"><section class="app-modal" role="dialog" aria-modal="true" aria-label="配置节目单"><div class="modal-title"><h2>配置节目单</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><form id="epg-form"><label>XMLTV 地址<input name="epg-url" type="url" placeholder="https://example.com/guide.xml" required aria-describedby="epg-field-error"></label><p class="form-note">支持 XMLTV / XMLTV.gz。节目单不会更改频道播放地址。</p><p id="epg-field-error" class="field-error" role="alert"></p><button class="primary-button" type="submit">保存并获取节目单</button></form></section></div>`;if(modal?.kind==='sync-review')return `<div class="modal-backdrop"><section class="app-modal" role="dialog" aria-modal="true" aria-label="确认同步差异"><div class="modal-title"><h2>确认同步差异</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div><p>只应用你勾选的项目，其他内容保留当前设备的设置。</p><div class="sync-options"><label><input type="checkbox" checked> 播放列表：当前 3 个 → 另一台设备 4 个</label><label><input type="checkbox"> 收藏：当前 3 个 → 另一台设备 8 个</label><label><input type="checkbox"> 清晰度：当前自动 → 另一台设备 1080p</label></div><button class="primary-button" data-boundary-action="finish-sync-review">应用所选项目</button><button class="remove-source" data-action="close-modal">取消，保留当前配置</button></section></div>`;return originalModalView()};
function showRecovery(loadingState,doneMessage,returnPage){const keepPlayer=player;applyScenario(loadingState,{navigateTo:false});if(keepPlayer)player=keepPlayer;recoveryTimer=setTimeout(()=>{applyScenario('normal',{navigateTo:false});if(returnPage)page=returnPage;if(keepPlayer)player=keepPlayer;render(true);notifyBoundary();toast(doneMessage+' · 演示')},1400)}
document.addEventListener('click',e=>{const favorited=e.target.closest('[data-favorite]');if(favorited&&scenario==='favorites-empty'&&favorites.length){savedScenarioFavorites=null;applyScenario('normal',{navigateTo:false});return}const played=e.target.closest('[data-play]');if(played&&scenarioInfo().scope==='player'){applyScenario('normal',{navigateTo:false});return}const b=e.target.closest('[data-boundary-action]');if(!b)return;const action=b.dataset.boundaryAction;switch(action){case 'channels':navigate('channels');notifyBoundary();break;case 'epg-config':modal={kind:'epg-config'};render(true);break;case 'retry-epg':showRecovery('epg-loading','节目单已更新','guide');break;case 'clear-search':case 'clear-state':applyScenario('normal',{navigateTo:false});query='';group='全部';render();notifyBoundary();break;case 'retry-network':applyScenario('normal',{navigateTo:false});toast('网络已恢复 · 演示');break;case 'source-settings':navigate('sources');notifyBoundary();break;case 'add-source':modal={kind:'source'};render(true);break;case 'preset':modal={kind:'preset'};render(true);break;case 'retry-import':applyScenario('normal',{navigateTo:false});toast('重新导入完成 · 演示');break;case 'close-player':player=null;miniPlayer=null;page='channels';applyScenario('normal',{navigateTo:false});break;case 'retry-player':showRecovery('player-connecting','频道已重新连接');break;case 'library':showLibrary=true;render(true);break;case 'pause-audio':paused=!paused;render(true);break;case 'retry-remote':b.textContent='正在搜索…';b.disabled=true;setTimeout(()=>{b.disabled=false;b.textContent='重新搜索';toast('暂未发现可连接设备 · 演示')},1200);break;case 'manual-remote':openOptions('手动连接示例',['192.168.1.108 · 客厅电视']);break;case 'permission-help':openOptions('局域网权限指引',['系统设置 → XPlayer → 开启本地网络']);break;case 'sync-review':modal={kind:'sync-review'};render(true);break;case 'finish-sync-review':modal=null;applyScenario('normal',{navigateTo:false});toast('已应用勾选项目 · 演示');break}});
document.addEventListener('submit',e=>{if(e.target.id==='source-form'&&['list-empty','import-error'].includes(scenario)){if(scenario==='list-empty'){savedScenarioSources=null;savedScenarioFavorites=null}applyScenario('normal',{navigateTo:false});return}if(e.target.id!=='epg-form')return;e.preventDefault();const value=new FormData(e.target).get('epg-url');let valid=false;try{valid=['http:','https:'].includes(new URL(value).protocol)}catch{}if(!valid){document.querySelector('#epg-field-error').textContent='请输入 http 或 https 的节目单地址。';return}modal=null;showRecovery('epg-loading','节目单已关联并更新','guide')});
if(params.get('page')==='player'&&scenario==='normal'){player=1;showLibrary=device==='desktop'||device==='ipad';render();notifyBoundary()}else applyScenario(scenario,{navigateTo:scenario!=='normal'});
